package com.campusconnect.chat; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.util.*; @RestController @RequestMapping("/api/chat") public class ChatController {private final ChatService service;public ChatController(ChatService s){service=s;} @PostMapping public ChatDtos.ChatResponse chat(@Valid @RequestBody ChatDtos.ChatRequest r,Principal p){return service.answer(r.message(),p);} @GetMapping("/history") public List<Map<String,Object>> history(Principal p){return service.history(p);} }
